us": "reported", "independent_source_count": 1}, {"id": "se_003", "text": "Une donation anonyme d''origine américaine de 20 millions d''euros a été faite pour créer des ateliers pédagogiques et une nouvelle galerie.", "type": "dedication", "dates": ["2024", "2026"], "people": [], "rank_score": 4.5, "source_url": "https://fr.wikipedia.org/wiki/Musée_d''Orsay", "source_domain": "fr.wikipedia.org", "source_sentence": "Le projet Orsay Grand Ouvert, qui prévoit de consacrer l''intégralité du musée aux collections et au public, bénéficie également d''une donation anonyme d''origine américaine de 20 millions d''euros pour créer en 2024 des ateliers pédagogiques de 650 m2 au 4e étage et en 2026 une nouvelle galerie de 1 200 m2 côté rue de Lille.", "syndication_log": {"sources": [{"url": "https://fr.wikipedia.org/wiki/Musée_d''Orsay", "domain": "fr.wikipedia.org"}], "total_in_group": 2, "independent_after_dedup": 1}, "corroboration_status": "reported", "independent_source_count": 1}, {"id": "se_004", "text": "La transformation de la gare en musée a été réalisée selon la volonté du président de la République Valéry Giscard d''Estaing.", "type": "intention", "dates": [], "people": ["Valéry Giscard d''Estaing", "François Mitterrand"], "is_satire": false, "rank_score": 4.0, "source_url": "https://fr.wikipedia.org/wiki/Musée_d''Orsay", "source_domain": "fr.wikipedia.org", "source_sentence": "Afin de permettre sa transformation en un musée des arts du XIXe siècle, selon la volonté du président de la République Valéry Giscard d''Estaing, confirmée par François Mitterrand.", "syndication_log": {"sources": [{"url": "https://fr.wikipedia.org/wiki/Musée_d''Orsay", "domain": "fr.wikipedia.org"}], "total_in_group": 1, "independent_after_dedup": 1}, "corroboration_status": "reported", "independent_source_count": 1}, {"id": "se_005", "text": "La transformation du bâtiment en musée des arts du XIXe siècle a été confirmée par le président de la République François Mitterrand.", "type": "intention", "dates": [], "people": ["François Mitterrand", "Valéry Giscard d''Estaing"], "is_satire": false, "rank_score": 4.0, "source_url": "https://fr.wikipedia.org/wiki/Musée_d''Orsay", "source_domain": "fr.wikipedia.org", "source_sentence": "Afin de permettre sa transformation en un musée des arts du XIXe siècle, selon la volonté du président de la République Valéry Giscard d''Estaing, confirmée par François Mitterrand.", "syndication_log": {"sources": [{"url": "https://fr.wikipedia.org/wiki/Musée_d''Orsay", "domain": "fr.wikipedia.org"}], "total_in_group": 1, "independent_after_dedup": 1}, "corroboration_status": "reported", "independent_source_count": 1}, {"id": "se_006", "text": "L''importante collection de 293 œuvres a été donnée sous réserve d''usufruit par les collectionneurs américains Spencer et Marlene Hays.", "type": "provenance", "dates": ["2016", "2019"], "people": ["Spencer Hays", "Marlene Hays", "Philippe Meyer", "Zeïneb Marcie-Rivière", "Jean-Pierre Marcie-Rivière"], "_merge_log": [{"pair": [0, 7], "a_text": "L''importante collection de 293 œuvres a été donnée sous réserve d''usufruit par l", "action": "merged", "b_text": "Une importante collection de 293 œuvres a été donnée sous réserve d''usufruit par", "a_domain": "fr.wikipedia.org", "b_domain": "fr.wikipedia.org", "conflicting": false, "same_subject": true}, {"pair": [1, 2], "a_text": "Une donation anonyme d''origine américaine de 20 millions d''euros a été faite pou", "action": "no_merge", "b_text": "Daniel Marchesseau a fait une donation de 5 millions d''euros pour relocaliser le", "a_domain": "fr.wikipedia.org", "b_domain": "fr.wikipedia.org", "conflicting": false, "same_subject": false}, {"pair": [4, 8], "a_text": "Le musée d''Orsay a ouvert ses portes dans la gare reconvertie le 9 décembre 1986", "action": "no_merge", "b_text": "Un réaménagement partiel des espaces du musée a été inauguré le 20 octobre 2011.", "a_domain": "fr.wikipedia.org", "b_domain": "fr.wikipedia.org", "conflicting": fal